import json, base64, pathlib, re
var=json.loads(pathlib.Path('run_trace/carrier_variant_datasets.json').read_text())
items=json.loads(pathlib.Path('run_trace/copied_history_datasets.json').read_text())
byname={i['name']:i for i in items}
script = r'''
import argparse, json, re, statistics, sys
from zipfile import ZipFile
import xml.etree.ElementTree as ET

NS = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

def colnum(cell_ref):
    m = re.match(r'([A-Z]+)', cell_ref)
    n = 0
    for ch in m.group(1):
        n = n * 26 + ord(ch) - 64
    return n - 1

def xlsx_rows(path):
    with ZipFile(path) as z:
        names = set(z.namelist())
        shared = []
        if 'xl/sharedStrings.xml' in names:
            root = ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root.findall(NS + 'si'):
                shared.append(''.join((t.text or '') for t in si.iter(NS + 't')))
        root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
        sheet_data = root.find(NS + 'sheetData')
        rows = []
        for row in sheet_data.findall(NS + 'row'):
            cells = {}
            for c in row.findall(NS + 'c'):
                ref = c.attrib.get('r', '')
                idx = colnum(ref)
                v = c.find(NS + 'v')
                if v is None:
                    val = ''
                else:
                    raw = v.text or ''
                    if c.attrib.get('t') == 's':
                        val = shared[int(raw)] if raw "'!= '"'' else ''
                    else:
                        val = raw
                cells[idx] = val
            if cells:
                rows.append([cells.get(i, '') for i in range(max(cells) + 1)])
        return rows

def normalize_header(x):
    return str(x).strip()

def load_chip_genes(path):
    genes = set()
    for row in xlsx_rows(path):
        if not row:
            continue
        value = str(row[0]).strip()
        if value:
            genes.add(value.upper())
    return genes

def load_carriers(path):
    rows = xlsx_rows(path)
    header = [normalize_header(x) for x in rows[0]]
    sid_i = header.index('Sample ID')
    blm_i = header.index('BLM Mutation Status')
    carriers = []
    for row in rows[1:]:
        if len(row) <= max(sid_i, blm_i):
            continue
        sid = str(row[sid_i]).strip()
        sid = sid[:-2] if sid.endswith('.0') else sid
        if str(row[blm_i]).strip() == 'Carrier':
            carriers.append(sid)
    return carriers

def find_header(rows):
    required = {'Zygosity', 'Variant Allele Freq', 'Gene Names', 'Sequence Ontology (Combined)', 'Effect (Combined)'}
    for i, row in enumerate(rows[:10]):
        labels = {normalize_header(x) for x in row}
        if required.issubset(labels):
            return i, [normalize_header(x) for x in row]
    raise RuntimeError('Could not find variant header row')

def parse_float(x):
    s = str(x).strip()
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None

def gene_matches(gene_value, chip_genes):
    tokens = re.split(r'[,;|/\\s]+', str(gene_value).upper())
    return any(tok in chip_genes for tok in tokens if tok)

def excluded_annotation(so, effect):
    text = (str(so) + ' ' + str(effect)).lower()
    return ('intron' in text) or ('intergenic' in text) or ('utr' in text)

def count_sample(path, chip_genes):
    rows = xlsx_rows(path)
    hidx, header = find_header(rows)
    col = {name: i for i, name in enumerate(header)}
    count = 0
    total_rows = 0
    after_chip = 0
    after_exclusions = 0
    for row in rows[hidx+1:]:
        if not any(str(x).strip() for x in row):
            continue
        total_rows += 1
        def get(name):
            i = col[name]
            return row[i] if i < len(row) else ''
        if not gene_matches(get('Gene Names'), chip_genes):
            continue
        after_chip += 1
        if str(get('Zygosity')).strip().lower() == 'reference':
            continue
        if excluded_annotation(get('Sequence Ontology (Combined)'), get('Effect (Combined)')):
            continue
        after_exclusions += 1
        vaf = parse_float(get('Variant Allele Freq'))
        if vaf is not None and vaf < 0.3:
            count += 1
    return count, total_rows, after_chip, after_exclusions

def format_number(x):
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x)

parser = argparse.ArgumentParser()
parser.add_argument('--chip', required=True)
parser.add_argument('--status', required=True)
parser.add_argument('--sample', nargs=2, action='append', metavar=('SAMPLE_ID', 'PATH'), required=True)
args = parser.parse_args()

chip_genes = load_chip_genes(args.chip)
carriers = load_carriers(args.status)
provided = {sid: path for sid, path in args.sample}
missing = sorted(set(carriers) - set(provided), key=lambda x: int(x) if x.isdigit() else x)
extra = sorted(set(provided) - set(carriers), key=lambda x: int(x) if x.isdigit() else x)
counts = []
rows_out = []
for sid in sorted(provided, key=lambda x: int(x) if x.isdigit() else x):
    count, total_rows, after_chip, after_exclusions = count_sample(provided[sid], chip_genes)
    counts.append(count)
    rows_out.append((sid, count, total_rows, after_chip, after_exclusions))
if not counts:
    raise RuntimeError('No carrier samples with provided variant files')
median_value = statistics.median(counts)
answer = format_number(median_value)
with open('answer.txt', 'w') as f:
    f.write(answer + '\\n')
with open('diagnostics.tsv', 'w') as f:
    f.write('sample_id\\tsomatic_chip_variant_count\\ttotal_variant_rows\\tchip_gene_rows\\tpost_annotation_zygosity_rows\\n')
    for row in rows_out:
        f.write('\\t'.join(map(str, row)) + '\\n')
    f.write('#carrier_samples_in_status\\t' + str(len(carriers)) + '\\n')
    f.write('#carrier_samples_with_variant_files\\t' + str(len(provided)) + '\\n')
    f.write('#missing_carrier_variant_files\\t' + ','.join(missing) + '\\n')
    f.write('#extra_provided_samples_not_carrier\\t' + ','.join(extra) + '\\n')
    f.write('#chip_gene_count\\t' + str(len(chip_genes)) + '\\n')
    f.write('#vaf_threshold\\t<0.3\\n')
    f.write('#excluded_annotations\\tintron,intergenic,utr\\n')
    f.write('#excluded_zygosity\\tReference\\n')
    f.write('#median\\t' + answer + '\\n')
